(()=>{const $=s=>document.querySelector(s);const loading=$('#loading'),app=$('#app'),results=$('#results');const progress=$('#progress'),reviewed=$('#reviewed'),bundleId=$('#bundleId'),bundleName=$('#bundleName'),voteBadge=$('#voteBadge'),counts=$('#counts'),textureGrid=$('#textureGrid'),noPreview=$('#noPreview'),prevBtn=$('#prevBtn'),nextBtn=$('#nextBtn'),noBtn=$('#noBtn'),maybeBtn=$('#maybeBtn'),yesBtn=$('#yesBtn'),resultsBtn=$('#resultsBtn'),backToReview=$('#backToReview'),orderSelect=$('#orderSelect'),yesList=$('#yesList'),maybeList=$('#maybeList'),copyYes=$('#copyYes'),copyMaybe=$('#copyMaybe'),copyBoth=$('#copyBoth'),copyFallback=$('#copyFallback'),dlg=$('#imageDialog'),dlgImg=$('#dialogImage'),dlgTitle=$('#dialogTitle'),dlgClose=$('#dialogClose');const KEY='wfgg.bundleQuickReview.v1';let manifest=null,items=[],idx=0;let votes={};try{votes=JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{votes={}}function save(){localStorage.setItem(KEY,JSON.stringify(votes))}function order(){const base=[...(manifest?.bundles||[])];if(orderSelect.value==='id')base.sort((a,b)=>a.bundleId-b.bundleId);else base.sort((a,b)=>(b.sceneScore||0)-(a.sceneScore||0)||a.bundleId-b.bundleId);items=base;idx=Math.max(0,Math.min(idx,items.length-1));render()}function badge(v){voteBadge.className='vote-badge'+(v?' '+v:'');voteBadge.textContent=v==='yes'?'✓ Oui':v==='maybe'?'? Incertain':v==='no'?'✕ Non':'Non classé'}function chip(label,val){if(!val)return'';return `<span class="count">${label} ${val}</span>`}function render(){if(!items.length)return;const b=items[idx];progress.textContent=`${idx+1} / ${items.length}`;const done=Object.keys(votes).filter(k=>votes[k]).length;reviewed.textContent=`${done} examinés`;bundleId.textContent=b.bundleId;bundleName.textContent=b.name||'(nom AssetBundle indisponible)';badge(votes[b.bundleId]||'');const c=b.typeCounts||{};counts.innerHTML=[chip('GameObject',c.GameObject),chip('Mesh',c.Mesh),chip('MeshRenderer',c.MeshRenderer),chip('Skinned',c.SkinnedMeshRenderer),chip('Terrain',c.Terrain),chip('Material',c.Material),chip('Texture2D',c.Texture2D),chip('Objets',b.objectCount)].join('');textureGrid.innerHTML='';for(const t of b.previewTextures||[]){const card=document.createElement('div');card.className='texture';card.innerHTML=`<button type="button"><img loading="lazy" alt="${esc(t.name)}" src="/lab/bundle-quick-review-data/${escAttr(t.file)}"><div class="texture-info"><strong>${esc(t.name||'(sans nom)')}</strong><span>${t.width}×${t.height} · ${esc(t.format||'')}</span></div></button>`;card.querySelector('button').addEventListener('click',()=>openImage(t));textureGrid.appendChild(card)}noPreview.classList.toggle('hidden',(b.previewTextures||[]).length>0);prevBtn.disabled=idx===0;nextBtn.disabled=idx===items.length-1}function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function escAttr(s){return String(s??'').replace(/"/g,'%22')}function step(n){const y=window.scrollY;idx=Math.max(0,Math.min(items.length-1,idx+n));render();requestAnimationFrame(()=>window.scrollTo({top:y,left:0,behavior:'auto'}))}function vote(v){const b=items[idx];votes[b.bundleId]=v;save();if(idx<items.length-1)step(1);else showResults()}function openImage(t){dlgTitle.textContent=`${t.name} — ${t.width}×${t.height}`;dlgImg.src=`/lab/bundle-quick-review-data/${t.file}`;if(typeof dlg.showModal==='function')dlg.showModal();else dlg.setAttribute('open','')}function closeDlg(){if(typeof dlg.close==='function')dlg.close();else dlg.removeAttribute('open')}function selected(v){return (manifest?.bundles||[]).filter(b=>votes[b.bundleId]===v).sort((a,b)=>a.bundleId-b.bundleId)}function row(b){const c=b.typeCounts||{};return `<div class="result-card"><strong>Bundle ${b.bundleId} — ${esc(b.name||'(sans nom)')}</strong><span>GO=${c.GameObject||0} Mesh=${c.Mesh||0} MeshRenderer=${c.MeshRenderer||0} Terrain=${c.Terrain||0} Material=${c.Material||0} Texture2D=${c.Texture2D||0}</span></div>`}function showResults(){app.classList.add('hidden');results.classList.remove('hidden');const ys=selected('yes'),ms=selected('maybe');yesList.innerHTML=`<h3>Oui (${ys.length})</h3>`+ys.map(row).join('');maybeList.innerHTML=`<h3>Incertains (${ms.length})</h3>`+ms.map(row).join('');window.scrollTo({top:0,behavior:'smooth'})}function back(){results.classList.add('hidden');app.classList.remove('hidden');render()}function textFor(arr,label){return arr.map(b=>{const c=b.typeCounts||{};return `${label} bundle=${b.bundleId} name=${b.name||'-'} GO=${c.GameObject||0} Mesh=${c.Mesh||0} MeshRenderer=${c.MeshRenderer||0} Skinned=${c.SkinnedMeshRenderer||0} Terrain=${c.Terrain||0} Material=${c.Material||0} Texture2D=${c.Texture2D||0}`}).join('\n')}async function copyText(txt){copyFallback.classList.add('hidden');try{await navigator.clipboard.writeText(txt)}catch{copyFallback.value=txt;copyFallback.classList.remove('hidden');copyFallback.focus();copyFallback.select()}}prevBtn.addEventListener('click',()=>step(-1));nextBtn.addEventListener('click',()=>step(1));noBtn.addEventListener('click',()=>vote('no'));maybeBtn.addEventListener('click',()=>vote('maybe'));yesBtn.addEventListener('click',()=>vote('yes'));resultsBtn.addEventListener('click',showResults);backToReview.addEventListener('click',back);orderSelect.addEventListener('change',order);dlgClose.addEventListener('click',closeDlg);copyYes.addEventListener('click',()=>copyText(textFor(selected('yes'),'YES')));copyMaybe.addEventListener('click',()=>copyText(textFor(selected('maybe'),'MAYBE')));copyBoth.addEventListener('click',()=>copyText([textFor(selected('yes'),'YES'),textFor(selected('maybe'),'MAYBE')].filter(Boolean).join('\n')));let touchX=null;$('#bundleCard').addEventListener('touchstart',e=>{touchX=e.changedTouches[0]?.clientX??null},{passive:true});$('#bundleCard').addEventListener('touchend',e=>{if(touchX==null)return;const x=e.changedTouches[0]?.clientX??touchX,d=x-touchX;touchX=null;if(Math.abs(d)>70)step(d<0?1:-1)},{passive:true});$('#bundleCard').addEventListener('keydown',e=>{if(e.target.matches('button,input,select,textarea'))return;if(e.key==='ArrowRight'){e.preventDefault();step(1)}if(e.key==='ArrowLeft'){e.preventDefault();step(-1)}});fetch('/lab/bundle-quick-review-data/manifest.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error(`manifest HTTP ${r.status}`);return r.json()}).then(m=>{manifest=m;items=[...(m.bundles||[])];loading.classList.add('hidden');app.classList.remove('hidden');order()}).catch(e=>{loading.textContent=`Données de revue absentes : ${e.message}. Lance le script de construction Termux.`})})();